"""Build a dependency-free scientific portfolio from reviewed project summaries."""
from pathlib import Path
from html import escape as e
import json

ROOT=Path(__file__).resolve().parent
DIST=ROOT/'dist'
PROJECTS=json.loads((ROOT/'content/projects.json').read_text())
BRANCH_LABELS={'quantum':'Quantum computing','biology':'Life Sciences','classical':'Optimization & Learning'}

def header(prefix=''):
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="{prefix}index.html">Senay Kahsay<span>Scientific portfolio</span></a><nav aria-label="Primary"><a href="{prefix}index.html#about">About</a><a href="{prefix}index.html#work">Work</a><a href="{prefix}index.html#contact">Contact</a></nav></div></header>'''

def footer(prefix=''):
    return '''<footer class="site-footer"><div class="shell footer-inner"><p>Senay Kahsay <span>Quantum computing · Life Sciences · Optimization &amp; Learning</span></p><p><a href="https://github.com/Sennaiai">GitHub</a><a href="https://www.linkedin.com/in/senay-kahsay">LinkedIn</a></p><small>© 2026 Senay Kahsay. Source methods, credits and limitations accompany each study.</small></div></footer>'''

def page(title,description,body,prefix=''):
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="robots" content="index,follow"><meta name="color-scheme" content="light"><title>{e(title)} · Senay Kahsay</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"></head><body>{header(prefix)}{body}{footer(prefix)}</body></html>'''

def card(p,feature=False):
    if p.get('display')=='mini':
        return f'''<article class="mini-study"><div><p class="eyebrow">{e(p['label'])}</p><h3><a href="projects/{p['slug']}.html">{e(p['title'])}</a></h3><p>{e(p['teaser'])}</p></div><a class="text-link" href="projects/{p['slug']}.html">View study<span class="sr-only">: {e(p['title'])}</span></a></article>'''
    return f'''<article class="project-card {'feature' if feature else ''} {p['branch']}"><div class="card-top"><span class="eyebrow">{e(p['label'])}</span><span class="project-type">{e(BRANCH_LABELS[p['branch']])}</span></div><h3><a href="projects/{p['slug']}.html">{e(p['title'])}</a></h3><p>{e(p['teaser'])}</p><p class="outcome">{e(p['outcome'])}</p><div class="card-bottom"><ul class="tags" aria-label="Methods">{''.join('<li>'+e(t)+'</li>' for t in p['tags'])}</ul><a class="text-link" href="projects/{p['slug']}.html">Read study<span class="sr-only">: {e(p['label'])}</span></a></div></article>'''

home='''<main id="main"><section class="hero shell"><div class="hero-copy"><p class="eyebrow">Computational research · Scientific software</p><h1>Quantum computing<br>and Life Sciences</h1><p class="hero-lede">Scientific software and tools for molecular studies, with explicit models, independent checks, reproducible implementations and CI-tested code.</p><p class="qualification">Master of Quantum Computing graduate from the University of Calgary, with a background in molecular biology (Honors) and philosophy.</p><div class="hero-links"><a class="button primary" href="#quantum">Quantum computing</a><a class="button secondary" href="#biology">Life Sciences</a><a class="button secondary" href="#classical">Optimization &amp; Learning</a></div></div><figure class="hero-figure"><img src="assets/research-sketch.svg" alt="HCN molecular-model sketch and saved H₂ total FCI energies in the STO-3G basis, at four bond lengths." width="480" height="400"><figcaption><p>Algorithm development: clear specifications, modular code, reference tests and continuous integration.</p><p class="hero-tools">Frontier AI development and productivity tools.</p></figcaption></figure></section>
<section class="about-section shell" id="about"><div><p class="eyebrow">About</p><h2>Bridging quantum computing<br>and life sciences.</h2></div><div class="about-copy"><p>I bridge quantum computing and the life sciences, with interests in quantum chemistry, molecular learning and computational approaches to biological systems. I investigate where quantum computing can offer an advantage over classical methods.</p><p>At Horizon Quantum, I worked on a quantum pipeline for modeling drug properties and tested its circuits against exact numerical calculations.</p></div></section>
<section class="work-section shell" id="work"><div class="section-heading" id="quantum"><div><p class="eyebrow">Quantum computing</p><h2>From molecular models<br>to measured comparisons.</h2></div></div><div class="project-grid">'''+''.join(card(p,i==0) for i,p in enumerate(PROJECTS) if p['branch']=='quantum')+'''</div></section>
<section class="biology-section" id="biology"><div class="shell"><div class="section-heading"><div><p class="eyebrow">Life Sciences</p><h2>Biological problems.</h2></div></div><div class="project-grid biology-grid">'''+card(next(p for p in PROJECTS if p['branch']=='biology'))+'''<aside class="workflow-panel"><p class="eyebrow">Genomic data workflow</p><ol><li>Contamination and ancestry PCs<span>VerifyBamID2 outputs</span></li><li>Reference alignment<span>Sample IDs and four principal components</span></li><li>Population assignment<span>KNN classification and visual summaries</span></li></ol><p>Implementation evidence is presented separately from unreported cohort performance.</p></aside></div></div></section>
<section class="classical-section shell" id="classical"><div class="section-heading"><div><p class="eyebrow">Optimization &amp; Learning</p><h2>Classical foundations.</h2></div></div><div class="project-grid">'''+''.join(card(p,p['slug']=='classical-learning') for p in PROJECTS if p['branch']=='classical' and p.get('display')!='mini')+'''</div>'''+''.join(card(p) for p in PROJECTS if p.get('display')=='mini')+'''</section>
<section class="contact-section" id="contact"><div class="shell contact-inner"><div><p class="eyebrow">Contact</p><h2>Let’s connect.</h2><p>For research and scientific-software conversations, connect through LinkedIn or explore the linked implementations.</p></div><div class="contact-links"><a class="button primary" href="https://www.linkedin.com/in/senay-kahsay">Connect on LinkedIn</a><a class="text-link" href="https://github.com/Sennaiai">GitHub profile</a></div></div></section></main>'''
DIST.mkdir(exist_ok=True);(DIST/'projects').mkdir(exist_ok=True)
(DIST/'index.html').write_text(page('Scientific portfolio','Senay Kahsay: quantum computing and life sciences. Scientific software, molecular learning and computational biology.',home))
for p in PROJECTS:
    figure=f'''<figure class="evidence-figure"><img src="../assets/{p['figure']}" alt="{e(p['alt'])}" loading="lazy"><figcaption>{e(p['caption'])}</figcaption></figure>''' if p['figure'] else ''
    sections=''.join(f'<section class="study-block"><h2>{label}</h2><p>{e(p[key])}</p></section>' for key,label in [('motivation','Motivation'),('implementation','Implementation'),('result','Results'),('limitation','Limitations')])
    note=f'<aside class="study-note"><strong>{e(p.get("note_label","Evidence boundary"))}</strong><p>{e(p["note"])}</p></aside>' if p.get('note') else ''
    related='<div class="related-studies"><span>Related studies</span>'+''.join(f'<a href="{e(v["href"])}">{e(v["label"])}</a>' for v in p.get('related',[]))+'</div>' if p.get('related') else ''
    body=f'''<main id="main" class="study-main"><section class="study-hero shell"><a class="breadcrumb" href="../index.html#{p['branch']}">{e(BRANCH_LABELS[p['branch']])}</a><p class="eyebrow">{e(p['label'])}</p><h1>{e(p['title'])}</h1><p class="study-lede">{e(p['teaser'])}</p><ul class="tags" aria-label="Methods">{''.join('<li>'+e(t)+'</li>' for t in p['tags'])}</ul></section><div class="shell"><div class="study-outcome"><span class="eyebrow">Main outcome</span><p>{e(p['outcome'])}</p></div><div class="study-grid">{sections}</div>{related}{figure}{note}<div class="source-links"><a class="button primary" href="{p['source']}">Project guide and source</a><a class="button secondary" href="{p['evidence']}">Evidence and checks</a><a class="text-link" href="../index.html#work">All selected work</a></div></div></main>'''
    (DIST/'projects'/f"{p['slug']}.html").write_text(page(p['label'],p['teaser'],body,'../'))
print(json.dumps({'pages':len(PROJECTS)+1,'projects':len(PROJECTS),'branches':list(BRANCH_LABELS)}))
